"""Write tools/qtable.hpp: the q each gpucheck point uses.

q is the largest prime below 2^W that is 1 mod 2N. Proving that for an 868-bit
integer is the bundle's job, not a device test's, so the answers are derived here
once and checked in — 217 hex digits are too many to retype.

    python tools/qtable.py
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from bundle import derive_q  # noqa: E402

POINTS = [(64, 32), (128, 64), (64, 128), (64, 254), (32, 868), (1024, 1747), (65536, 64)]

lines = [
    "// Generated by tools/qtable.py from the same derive_q the bundle uses.",
    "// Do not edit: rerun the script instead.",
    "#pragma once",
    "",
    "struct KnownPoint {",
    "    unsigned N, W;",
    "    const char* hex;",
    "};",
    "",
    "inline const KnownPoint kPoints[] = {",
]
for n, w in POINTS:
    q = derive_q(n, w)
    assert q.bit_length() == w, (n, w, q.bit_length())
    lines.append(f'    {{{n}, {w}, "{q:x}"}},')
lines += ["};", ""]

out = Path(__file__).parent.joinpath("qtable.hpp")
out.write_text("\n".join(lines))
print(f"wrote {out} with {len(POINTS)} points")
